"use strict";

(function installRingTraceModel(root) {
  const ARTIFACT_SCHEMA = 4;
  const MAX_DIAGNOSTIC_STEPS = 4_096;
  const GENERATED_COMMENT =
    "// Generated by `cargo run -p kr-runtime-trace-tool --example generate_ring_trace`.";
  const GENERATED_ASSIGNMENT = "globalThis.RING_TRACE_DATA =";
  const {
    exactUnsigned,
    parseJsonArtifact,
    positiveVersion,
    record,
    safeUnsigned,
    string,
  } = root.TRACE_VIEWER_CORE;
  const OUTCOMES = new Set([
    "success",
    "rejected",
    "crash",
    "recovered",
    "unknown",
  ]);
  const CERTAINTIES = new Set([
    "not_applied",
    "applied",
    "may_have_applied",
    "unknown",
  ]);
  function validatePhysical(physical, configCapacity, cursors, name) {
    const value = record(physical, name);
    const capacity = exactUnsigned(
      value.data_capacity_bytes,
      `${name}.data_capacity_bytes`,
    );
    if (capacity === 0n) {
      throw new Error(`${name}.data_capacity_bytes must be non-zero`);
    }
    if (capacity !== configCapacity) {
      throw new Error(
        `${name}.data_capacity_bytes differs from config.data_capacity_bytes`,
      );
    }

    const protectedBytes = exactUnsigned(
      value.protected_bytes,
      `${name}.protected_bytes`,
    );
    const freeBytes = exactUnsigned(value.free_bytes, `${name}.free_bytes`);
    if (protectedBytes + freeBytes !== capacity) {
      throw new Error(
        `${name}.protected_bytes plus free_bytes must equal data_capacity_bytes`,
      );
    }

    const offsets = {};
    for (
      const field of [
        "durable_head_offset",
        "durable_tail_offset",
        "accepted_tail_offset",
      ]
    ) {
      const offset = exactUnsigned(value[field], `${name}.${field}`);
      if (offset >= capacity) {
        throw new Error(`${name}.${field} must be inside the physical ring`);
      }
      offsets[field] = offset;
    }
    const protectedEnd = (offsets.durable_head_offset + protectedBytes) %
      capacity;
    if (offsets.accepted_tail_offset !== protectedEnd) {
      throw new Error(
        `${name}.accepted_tail_offset disagrees with the protected interval`,
      );
    }
    if (
      cursors.durableHead === cursors.durableTail &&
      (offsets.durable_head_offset !== 0n || offsets.durable_tail_offset !== 0n)
    ) {
      throw new Error(`${name} empty durable interval must use zero offsets`);
    }
    const generation = exactUnsigned(
      value.metadata_generation,
      `${name}.metadata_generation`,
    );
    if (generation === 0n) {
      throw new Error(`${name}.metadata_generation must be non-zero`);
    }
    if (typeof value.recovery_required !== "boolean") {
      throw new Error(`${name}.recovery_required must be boolean`);
    }
  }

  function validateStatus(status, config, name) {
    const value = record(status, name);
    const acceptedHead = exactUnsigned(
      value.accepted_head,
      `${name}.accepted_head`,
    );
    const acceptedTail = exactUnsigned(
      value.accepted_tail,
      `${name}.accepted_tail`,
    );
    const durableHead = exactUnsigned(
      value.durable_head,
      `${name}.durable_head`,
    );
    const durableTail = exactUnsigned(
      value.durable_tail,
      `${name}.durable_tail`,
    );
    if (acceptedHead > acceptedTail) {
      throw new Error(`${name} accepted head exceeds accepted tail`);
    }
    if (durableHead > durableTail) {
      throw new Error(`${name} durable head exceeds durable tail`);
    }
    if (durableHead > acceptedHead) {
      throw new Error(`${name} durable head exceeds accepted head`);
    }
    if (durableTail > acceptedTail) {
      throw new Error(`${name} durable tail exceeds accepted tail`);
    }
    if (acceptedHead > durableTail) {
      throw new Error(`${name} accepted head exceeds durable tail`);
    }

    const acceptedLiveRecords = safeUnsigned(
      value.accepted_live_records,
      `${name}.accepted_live_records`,
    );
    const acceptedLivePayloadBytes = safeUnsigned(
      value.accepted_live_payload_bytes,
      `${name}.accepted_live_payload_bytes`,
    );
    const retainedRecords = safeUnsigned(
      value.retained_records,
      `${name}.retained_records`,
    );
    const retainedPayloadBytes = safeUnsigned(
      value.retained_payload_bytes,
      `${name}.retained_payload_bytes`,
    );
    const pendingReclaimRecords = safeUnsigned(
      value.pending_reclaim_records,
      `${name}.pending_reclaim_records`,
    );
    const pendingReclaimPayloadBytes = safeUnsigned(
      value.pending_reclaim_payload_bytes,
      `${name}.pending_reclaim_payload_bytes`,
    );
    const maxLiveRecords = safeUnsigned(
      value.max_live_records,
      `${name}.max_live_records`,
    );
    const maxLivePayloadBytes = safeUnsigned(
      value.max_live_payload_bytes,
      `${name}.max_live_payload_bytes`,
    );

    if (maxLiveRecords !== config.maxLiveRecords) {
      throw new Error(
        `${name}.max_live_records differs from config.max_live_records`,
      );
    }
    if (maxLivePayloadBytes !== config.maxLivePayloadBytes) {
      throw new Error(
        `${name}.max_live_payload_bytes differs from config.max_live_payload_bytes`,
      );
    }
    if (acceptedLiveRecords > maxLiveRecords) {
      throw new Error(`${name}.accepted_live_records exceeds max_live_records`);
    }
    if (acceptedLivePayloadBytes > maxLivePayloadBytes) {
      throw new Error(
        `${name}.accepted_live_payload_bytes exceeds max_live_payload_bytes`,
      );
    }
    if (retainedRecords > maxLiveRecords) {
      throw new Error(`${name}.retained_records exceeds max_live_records`);
    }
    if (retainedPayloadBytes > maxLivePayloadBytes) {
      throw new Error(
        `${name}.retained_payload_bytes exceeds max_live_payload_bytes`,
      );
    }
    if (BigInt(acceptedLiveRecords) !== acceptedTail - acceptedHead) {
      throw new Error(
        `${name}.accepted_live_records differs from its cursor interval`,
      );
    }
    if (BigInt(pendingReclaimRecords) !== acceptedHead - durableHead) {
      throw new Error(
        `${name}.pending_reclaim_records differs from its cursor interval`,
      );
    }
    if (BigInt(retainedRecords) !== acceptedTail - durableHead) {
      throw new Error(
        `${name}.retained_records differs from its cursor interval`,
      );
    }
    if (retainedRecords !== acceptedLiveRecords + pendingReclaimRecords) {
      throw new Error(
        `${name}.retained_records has inconsistent reclaim accounting`,
      );
    }
    if (
      retainedPayloadBytes !==
        acceptedLivePayloadBytes + pendingReclaimPayloadBytes
    ) {
      throw new Error(
        `${name}.retained_payload_bytes has inconsistent reclaim accounting`,
      );
    }

    if (value.physical !== null) {
      validatePhysical(
        value.physical,
        config.capacity,
        { durableHead, durableTail },
        `${name}.physical`,
      );
    }
  }

  function validateData(raw) {
    const artifact = record(raw, "ring trace");
    if (artifact.schema !== ARTIFACT_SCHEMA) {
      throw new Error(
        `unsupported ring trace schema ${String(artifact.schema)}`,
      );
    }
    string(artifact.scenario, "scenario");
    string(artifact.source_test, "source_test");
    string(artifact.provider, "provider");

    const runtime = record(artifact.runtime, "runtime");
    positiveVersion(runtime.reproduction_schema, "runtime.reproduction_schema");
    positiveVersion(runtime.checkpoint_schema, "runtime.checkpoint_schema");
    positiveVersion(runtime.rng_version, "runtime.rng_version");
    for (
      const field of [
        "seed",
        "max_tasks",
        "max_timers",
        "max_steps_per_run",
        "total_steps",
        "next_enqueue_sequence",
        "next_timer_sequence",
        "next_timer_id",
      ]
    ) {
      exactUnsigned(runtime[field], `runtime.${field}`);
    }
    const runtimeNow = exactUnsigned(runtime.now_ns, "runtime.now_ns");
    if (runtime.max_time_ns !== null) {
      exactUnsigned(runtime.max_time_ns, "runtime.max_time_ns");
    }

    const configValue = record(artifact.config, "config");
    const config = {
      capacity: exactUnsigned(
        configValue.data_capacity_bytes,
        "config.data_capacity_bytes",
      ),
      maxLiveRecords: safeUnsigned(
        configValue.max_live_records,
        "config.max_live_records",
      ),
      maxLivePayloadBytes: safeUnsigned(
        configValue.max_live_payload_bytes,
        "config.max_live_payload_bytes",
      ),
    };
    if (config.capacity === 0n) {
      throw new Error("config.data_capacity_bytes must be non-zero");
    }
    exactUnsigned(configValue.storage_latency_ns, "config.storage_latency_ns");

    if (!Array.isArray(artifact.steps) || artifact.steps.length === 0) {
      throw new Error("ring trace contains no diagnostic steps");
    }
    if (artifact.steps.length > MAX_DIAGNOSTIC_STEPS) {
      throw new Error(
        `ring trace exceeds the ${MAX_DIAGNOSTIC_STEPS}-step viewer limit`,
      );
    }
    let previousSequence = -1;
    let previousCompletion = null;
    const steps = artifact.steps.map((candidate, index) => {
      const step = record(candidate, `step ${index}`);
      const sequence = safeUnsigned(step.sequence, `step ${index}.sequence`);
      if (sequence <= previousSequence) {
        throw new Error(
          "diagnostic presentation sequences must increase strictly",
        );
      }
      previousSequence = sequence;

      string(step.phase, `step ${sequence}.phase`);
      string(step.operation, `step ${sequence}.operation`);
      string(step.description, `step ${sequence}.description`);
      string(step.summary, `step ${sequence}.summary`);
      record(step.fields, `step ${sequence}.fields`);
      if (!OUTCOMES.has(step.outcome)) {
        throw new Error(`step ${sequence}.outcome is not supported`);
      }
      if (step.certainty !== null && !CERTAINTIES.has(step.certainty)) {
        throw new Error(`step ${sequence}.certainty is not supported`);
      }

      const startedAt = exactUnsigned(
        step.started_at_ns,
        `step ${sequence}.started_at_ns`,
      );
      const completedAt = exactUnsigned(
        step.completed_at_ns,
        `step ${sequence}.completed_at_ns`,
      );
      const duration = exactUnsigned(
        step.duration_ns,
        `step ${sequence}.duration_ns`,
      );
      if (completedAt < startedAt) {
        throw new Error(`step ${sequence} completes before it starts`);
      }
      if (duration !== completedAt - startedAt) {
        throw new Error(
          `step ${sequence} duration does not match its time interval`,
        );
      }
      if (previousCompletion !== null && startedAt < previousCompletion) {
        throw new Error(
          `step ${sequence} starts before the prior step completes`,
        );
      }
      if (completedAt > runtimeNow) {
        throw new Error(`step ${sequence} completes after runtime.now_ns`);
      }
      previousCompletion = completedAt;
      if (step.status !== null) {
        validateStatus(step.status, config, `step ${sequence}.status`);
      }

      return {
        ...step,
        _startedAt: startedAt,
        _completedAt: completedAt,
        _duration: duration,
        _outcome: step.outcome,
      };
    });

    return { raw: artifact, steps };
  }

  function parseArtifactText(text) {
    return parseJsonArtifact(text, {
      assignment: GENERATED_ASSIGNMENT,
      generatedComment: GENERATED_COMMENT,
      description: "ring trace",
    });
  }

  root.RING_TRACE_MODEL = Object.freeze({
    artifactSchema: ARTIFACT_SCHEMA,
    parseArtifactText,
    validateData,
  });
})(globalThis);
